from django.core.management.base import BaseCommand
from django.db import connection
import json, zlib, base64

FIELDS = ["id", "cpf", "nome_retornado", "status_cpf", "total_processos", "resultado_json", "pdf_file", "transaction_id", "origem", "criado_em", "atualizado_em", "funcionario_id", "solicitante_id"]

DATA_B64 = """"""

class Command(BaseCommand):
    help = 'Importa ConsultaProcesso do backup local'

    def handle(self, *args, **options):
        data = json.loads(zlib.decompress(base64.b64decode(DATA_B64)).decode('utf-8'))
        placeholders = ','.join(['%s'] * len(FIELDS))
        field_names = ','.join(FIELDS)
        with connection.cursor() as c:
            c.execute("DELETE FROM cadastros_consultaprocesso")
            for row in data:
                # resultado_json precisa ser string JSON para o PostgreSQL
                row_list = list(row)
                idx = FIELDS.index('resultado_json')
                if isinstance(row_list[idx], (dict, list)):
                    row_list[idx] = json.dumps(row_list[idx])
                c.execute(
                    f"INSERT INTO cadastros_consultaprocesso ({field_names}) VALUES ({placeholders})",
                    row_list
                )
            c.execute("SELECT setval(\'cadastros_consultaprocesso_id_seq\', (SELECT MAX(id) FROM cadastros_consultaprocesso))")
        self.stdout.write(self.style.SUCCESS(f'Importados: {len(data)} registros de ConsultaProcesso.'))
